+                  className: "button-secondary",
+                  attributes: 'id="cancel-dialog"',
+                })}
+                ${Button({
+                  label: "Delete image",
+                  className: "button-danger",
+                  attributes: 'id="confirm-delete"',
+                })}
+              </div>
