       function ConfirmDeleteDialog() {
         return `
           <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
             <div class="dialog-card">
               <div class="dialog-icon" aria-hidden="true">!</div>
               <h2 id="dialog-title">Delete this image?</h2>
               <p id="dialog-description">
                 This will permanently remove the image from your library. Anyone using it in future work will need to upload it again.
               </p>
               <div class="dialog-actions">
                 ${Button({
                   label: "Cancel",
                   className: "button-secondary",
                   attributes: 'id="cancel-dialog"',
                 })}
                 ${Button({
                   label: "Delete image",
                   className: "button-danger",
                   attributes: 'id="confirm-delete"',
                 })}
               </div>
             </div>
           </dialog>
         `;
       }

       function App() {
         return `
           <main class="shell">
             <section class="hero" aria-labelledby="page-title">
               <div>
                 <span class="eyebrow">Image library preview</span>
                 <h1 id="page-title">Review a visual before you keep it or remove it.</h1>
                 <p>
                   This product-style preview gives teammates a clean place to inspect metadata, confirm the asset choice, and remove it with a clear confirmation step.
                 </p>
               </div>
               ${HeroStats()}
             </section>
             <section class="grid">
               ${PreviewCard()}
               ${DetailsCard()}
             </section>
           </main>
           ${ConfirmDeleteDialog()}
         `;
       }

       function bindEvents() {
         const dialog = document.getElementById("delete-dialog");
         const openButton = document.getElementById("open-dialog");
         const cancelButton = document.getElementById("cancel-dialog");
         const confirmButton = document.getElementById("confirm-delete");

         if (openButton && dialog) {
           openButton.addEventListener("click", () => {
             state.isDialogOpen = true;
             dialog.showModal();
           });
         }

         if (cancelButton && dialog) {
           cancelButton.addEventListener("click", () => {
             state.isDialogOpen = false;
             dialog.close();
           });
         }

         if (confirmButton && dialog) {
           confirmButton.addEventListener("click", () => {
             state.isDeleted = true;
             state.isDialogOpen = false;
             dialog.close();
             render();
           });
         }

         if (dialog) {
           dialog.addEventListener("cancel", () => {
             state.isDialogOpen = false;
           });
         }
       }

       function render() {
         document.getElementById("app").innerHTML = App();
         bindEvents();
       }

       render();
